<?php
namespace App\Http\Controllers;
use App\Models\{Post,Category}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class PostController extends Controller { public function index(Request $r){$posts=$r->user()->posts()->with('category')->latest()->paginate(15);return view('dashboard.posts',compact('posts'));} public function create(){return view('dashboard.posts-form',['post'=>new Post,'categories'=>Category::where('active',true)->orderBy('sort_order')->get()]);} public function store(Request $r){$data=$r->validate(['title'=>'required|string|max:180','category_id'=>'required|exists:categories,id','content'=>'required|string|max:100000','excerpt'=>'nullable|string|max:500','external_image_url'=>'nullable|url:http,https|max:2000','featured_image'=>'nullable|image|max:5120','anonymous'=>'boolean']);$data['slug']=Str::slug($data['title']).'-'.Str::lower(Str::random(6));$data['anonymous']=$r->boolean('anonymous');$data['status']='pending';if($r->hasFile('featured_image'))$data['featured_image']=$r->file('featured_image')->store('posts','public');$r->user()->posts()->create($data);return redirect('/dashboard/posts')->with('status','Post submitted for moderation.');} public function edit(Post $post){abort_unless($post->user_id===request()->user()->id&&$post->status!=='approved',403);return view('dashboard.posts-form',['post'=>$post,'categories'=>Category::where('active',true)->get()]);} public function update(Request $r,Post $post){abort_unless($post->user_id===request()->user()->id&&$post->status!=='approved',403);$data=$r->validate(['title'=>'required|string|max:180','category_id'=>'required|exists:categories,id','content'=>'required|string|max:100000','excerpt'=>'nullable|string|max:500']);$post->update($data+['status'=>'pending']);return redirect('/dashboard/posts');} }
